<?php
require_once __DIR__ . '/auth.php';
function dashboardValue($pdo, $expression, $where = '') { return (float)$pdo->query("SELECT $expression FROM orders WHERE status <> 'Annulée' $where")->fetchColumn(); }
function dashboardChange($current, $previous) { return $previous > 0 ? round((($current - $previous) / $previous) * 100, 1) : 0; }
$stats = [];
$stats['sales'] = dashboardValue($pdo, 'COALESCE(SUM(total_amount),0)');
$stats['today'] = dashboardValue($pdo, 'COALESCE(SUM(total_amount),0)', 'AND created_at >= CURDATE()');
$stats['week'] = dashboardValue($pdo, 'COALESCE(SUM(total_amount),0)', 'AND created_at >= DATE_SUB(NOW(), INTERVAL 7 DAY)');
$stats['month'] = dashboardValue($pdo, 'COALESCE(SUM(total_amount),0)', 'AND created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)');
$stats['weekChange'] = dashboardChange($stats['week'], dashboardValue($pdo, 'COALESCE(SUM(total_amount),0)', 'AND created_at >= DATE_SUB(NOW(), INTERVAL 14 DAY) AND created_at < DATE_SUB(NOW(), INTERVAL 7 DAY)'));
$stats['monthChange'] = dashboardChange($stats['month'], dashboardValue($pdo, 'COALESCE(SUM(total_amount),0)', 'AND created_at >= DATE_SUB(NOW(), INTERVAL 60 DAY) AND created_at < DATE_SUB(NOW(), INTERVAL 30 DAY)'));
$stats['orders'] = (int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn();
$stats['todayOrders'] = (int)$pdo->query('SELECT COUNT(*) FROM orders WHERE created_at >= CURDATE()')->fetchColumn();
$stats['weekOrders'] = (int)$pdo->query('SELECT COUNT(*) FROM orders WHERE created_at >= DATE_SUB(NOW(), INTERVAL 7 DAY)')->fetchColumn();
$stats['average'] = $stats['orders'] ? $stats['sales'] / $stats['orders'] : 0;
$stats['stockValue'] = (float)$pdo->query('SELECT COALESCE(SUM(price * stock),0) FROM products')->fetchColumn();
$alerts = ['out' => (int)$pdo->query('SELECT COUNT(*) FROM products WHERE stock = 0')->fetchColumn(), 'low' => (int)$pdo->query('SELECT COUNT(*) FROM products WHERE stock > 0 AND stock < 5')->fetchColumn(), 'pending' => (int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status = 'En attente' AND created_at < DATE_SUB(NOW(), INTERVAL 48 HOUR)")->fetchColumn()];
$salesChart = $pdo->query("SELECT DATE(created_at) day, COALESCE(SUM(total_amount),0) amount FROM orders WHERE status <> 'Annulée' AND created_at >= DATE_SUB(CURDATE(), INTERVAL 29 DAY) GROUP BY DATE(created_at) ORDER BY day")->fetchAll();
$statusChart = $pdo->query('SELECT status, COUNT(*) total FROM orders GROUP BY status')->fetchAll();
$topProducts = $pdo->query("SELECT p.name, SUM(oi.quantity) total FROM order_items oi JOIN products p ON p.id = oi.product_id JOIN orders o ON o.id = oi.order_id AND o.status <> 'Annulée' GROUP BY oi.product_id ORDER BY total DESC LIMIT 5")->fetchAll();
$recent = $pdo->query('SELECT * FROM orders ORDER BY created_at DESC LIMIT 10')->fetchAll();
$neverSold = $pdo->query("SELECT p.name FROM products p LEFT JOIN order_items oi ON oi.product_id = p.id WHERE oi.id IS NULL ORDER BY p.name")->fetchAll();
$newCustomers = (int)$pdo->query("SELECT COUNT(*) FROM customers WHERE created_at >= DATE_FORMAT(CURDATE(), '%Y-%m-01')")->fetchColumn();
$admin = $pdo->prepare('SELECT last_login FROM admins WHERE id = ?'); $admin->execute([$_SESSION['admin_id']]); $lastLogin = $admin->fetchColumn();
$labels = $amounts = []; foreach ($salesChart as $row) { $labels[] = $row['day']; $amounts[] = (float)$row['amount']; }
$statusLabels = $statusValues = []; foreach ($statusChart as $row) { $statusLabels[] = $row['status']; $statusValues[] = (int)$row['total']; }
$topLabels = $topValues = []; foreach ($topProducts as $row) { $topLabels[] = $row['name']; $topValues[] = (int)$row['total']; }
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Dashboard | Woodin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container"><a class="navbar-brand text-warning" href="index.php">WOODIN ADMIN</a><div><a class="btn btn-outline-light btn-sm" href="products.php">Produits</a> <a class="btn btn-outline-light btn-sm" href="customers.php">Clients</a> <a class="btn btn-outline-light btn-sm" href="orders.php">Commandes</a> <a class="btn btn-warning btn-sm" href="logout.php">Déconnexion</a></div></div></nav><main class="container py-4"><h1>Centre de pilotage</h1><p class="text-muted">Bienvenue, <?= e($_SESSION['admin_username']) ?>.</p><?php if ($alerts['out']): ?><div class="alert alert-danger">Ruptures de stock : <strong><?= $alerts['out'] ?></strong> <a href="products.php?filter=rupture">Voir les produits</a></div><?php endif; ?><?php if ($alerts['low']): ?><div class="alert alert-warning">Stock faible : <strong><?= $alerts['low'] ?></strong> produit(s).</div><?php endif; ?><?php if ($alerts['pending']): ?><div class="alert alert-info">Commandes en attente depuis 48 h : <strong><?= $alerts['pending'] ?></strong> <a href="orders.php?filter=en_attente_48h">Traiter maintenant</a></div><?php endif; ?><div class="row g-3"><div class="col-md-3"><div class="card p-3 h-100"><small>CA total</small><strong class="fs-4"><?= number_format($stats['sales'],0,',',' ') ?> FCFA</strong></div></div><div class="col-md-3"><div class="card p-3 h-100"><small>CA aujourd'hui</small><strong class="fs-4"><?= number_format($stats['today'],0,',',' ') ?> FCFA</strong></div></div><div class="col-md-3"><div class="card p-3 h-100"><small>CA 7 jours</small><strong class="fs-4"><?= number_format($stats['week'],0,',',' ') ?> FCFA</strong><span class="<?= $stats['weekChange'] >= 0 ? 'text-success' : 'text-danger' ?>"><?= $stats['weekChange'] >= 0 ? '+' : '' ?><?= $stats['weekChange'] ?>% vs période précédente</span></div></div><div class="col-md-3"><div class="card p-3 h-100"><small>CA 30 jours</small><strong class="fs-4"><?= number_format($stats['month'],0,',',' ') ?> FCFA</strong><span class="<?= $stats['monthChange'] >= 0 ? 'text-success' : 'text-danger' ?>"><?= $stats['monthChange'] >= 0 ? '+' : '' ?><?= $stats['monthChange'] ?>% vs période précédente</span></div></div><div class="col-md-3"><div class="card p-3"><small>Commandes total / aujourd'hui / semaine</small><strong><?= $stats['orders'] ?> / <?= $stats['todayOrders'] ?> / <?= $stats['weekOrders'] ?></strong></div></div><div class="col-md-3"><div class="card p-3"><small>Panier moyen</small><strong><?= number_format($stats['average'],0,',',' ') ?> FCFA</strong></div></div><div class="col-md-3"><div class="card p-3"><small>Valeur du stock</small><strong><?= number_format($stats['stockValue'],0,',',' ') ?> FCFA</strong></div></div><div class="col-md-3"><div class="card p-3"><small>Nouveaux clients ce mois</small><strong><?= $newCustomers ?></strong></div></div></div><div class="row g-3 mt-2"><div class="col-lg-7"><div class="card p-3"><h2 class="h5">Ventes des 30 derniers jours</h2><canvas id="salesChart"></canvas></div></div><div class="col-lg-5"><div class="card p-3"><h2 class="h5">Commandes par statut</h2><canvas id="statusChart"></canvas></div></div><div class="col-lg-6"><div class="card p-3"><h2 class="h5">Top 5 produits vendus</h2><canvas id="topChart"></canvas></div></div><div class="col-lg-6"><div class="card p-3"><h2 class="h5">Dernières commandes</h2><div class="table-responsive"><table class="table table-sm"><tbody><?php foreach ($recent as $order): ?><tr><td>#<?= (int)$order['id'] ?></td><td><?= e($order['customer_name']) ?></td><td><?= number_format($order['total_amount'],0,',',' ') ?> FCFA</td><td><?= e($order['status']) ?></td></tr><?php endforeach; ?></tbody></table></div><a href="orders.php">Voir toutes les commandes</a></div></div></div><div class="row g-3 mt-2"><div class="col-md-6"><div class="card p-3"><h2 class="h5">Produits jamais vendus</h2><p><?= $neverSold ? e(implode(', ', array_column($neverSold, 'name'))) : 'Aucun' ?></p><small class="text-muted">TODO : ajouter confirmed_at et shipped_at pour calculer le délai moyen de traitement.</small></div></div><div class="col-md-6"><div class="card p-3"><h2 class="h5">Actions rapides</h2><a class="btn btn-warning m-1" href="products.php?action=add">Nouveau produit</a><a class="btn btn-dark m-1" href="orders.php?filter=en_attente">Commandes à traiter</a><a class="btn btn-outline-dark m-1" href="export_sales.php?period=month">Exporter ventes du mois (CSV)</a><a class="btn btn-outline-dark m-1" href="backup_db.php">Sauvegarder la base de données</a></div></div></div><p class="small text-muted mt-4">Dernière connexion admin : <?= e($lastLogin ? $lastLogin : 'Première connexion') ?> · Dernière sauvegarde : téléchargement à la demande.</p></main><script>new Chart(document.getElementById('salesChart'),{type:'line',data:{labels:<?= json_encode($labels) ?>,datasets:[{label:'CA (FCFA)',data:<?= json_encode($amounts) ?>,borderColor:'#8b0000',backgroundColor:'rgba(139,0,0,.1)',fill:true,tension:.25}]},options:{responsive:true}});new Chart(document.getElementById('statusChart'),{type:'doughnut',data:{labels:<?= json_encode($statusLabels) ?>,datasets:[{data:<?= json_encode($statusValues) ?>,backgroundColor:['#f5c518','#278b4e','#13606c','#8b0000','#666']}]}});new Chart(document.getElementById('topChart'),{type:'bar',data:{labels:<?= json_encode($topLabels) ?>,datasets:[{label:'Quantité',data:<?= json_encode($topValues) ?>,backgroundColor:'#f5c518'}]},options:{indexAxis:'y',responsive:true}});</script></body></html>
